module TopModule (
    input  logic clk,
    input  logic reset,
    input  logic data,
    output logic start_shifting
);

    typedef enum logic [2:0] {
        S0   = 3'd0,
        S1   = 3'd1,
        S2   = 3'd2,
        S3   = 3'd3,
        S4   = 3'd4
    } state_t;

    state_t current_state, next_state;

    always_ff @(posedge clk) begin
        if (reset) begin
            current_state <= S0;
        end else begin
            current_state <= next_state;
        end
    end

    always_comb begin
        next_state = current_state;
        case (current_state)
            S0: begin
                if (data) next_state = S1;
                else      next_state = S0;
            end
            S1: begin
                if (data) next_state = S2;
                else      next_state = S0;
            end
            S2: begin
                if (data) next_state = S2;
                else      next_state = S3;
            end
            S3: begin
                if (data) next_state = S4;
                else      next_state = S0;
            end
            S4: begin
                next_state = S4;
            end
            default: next_state = S0;
        endcase
    end

    assign start_shifting = (current_state == S4);

endmodule

